from fractions import Fraction

R = [Fraction(7, 3), Fraction(11, 4), Fraction(2024, 5), Fraction(109, 11), Fraction(3, 71), Fraction(5, 204)]
r0 = Fraction(11, 3)

def check_relation(r1, r2):
    rel = []
    # Check r1 + r2 = 0
    if r1 + r2 == 0:
        rel.append("Sum is 0")
    # Check r1 + r2 = 1
    elif r1 + r2 == 1:
        rel.append("Sum is 1")
    # Check r1 * r2 = 1
    elif r1 * r2 == 1:
        rel.append("Product is 1")
    return rel

print("--- Relations with r0 = 11/3 ---")
for r in R:
    relations = check_relation(r0, r)
    if relations:
        print(f"f(r0) and f({r}) are related: {relations}")

print("\n--- Relations within R ---")
for i in range(len(R)):
    for j in range(i + 1, len(R)):
        r1 = R[i]
        r2 = R[j]
        relations = check_relation(r1, r2)
        if relations:
            print(f"f({r1}) and f({r2}) are related: {relations}")
